xpath.script:
(function() {
    var header = document.getElementById('dimsop_header');
    var lastScroll = 0;
    var scrollThreshold = 80;

    window.addEventListener('scroll', function() {
        var currentScroll = window.pageYOffset || document.documentElement.scrollTop;
        if (currentScroll > scrollThreshold) {
            if (currentScroll > lastScroll) {
                header.classList.add('dimsop-header-hidden');
                header.classList.remove('dimsop-header-visible');
            } else {
                header.classList.remove('dimsop-header-hidden');
                header.classList.add('dimsop-header-visible');
            }
        } else {
            header.classList.remove('dimsop-header-hidden');
            header.classList.remove('dimsop-header-visible');
        }
        lastScroll = currentScroll;
    }, { passive: true });

    var progressBar = document.getElementById('dimsop-scroll-progress');
    if (progressBar) {
        window.addEventListener('scroll', function() {
            var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            var docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            var scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
            progressBar.style.width = scrollPercent + '%';
        }, { passive: true });
    }

    function getSections() {
        var arr = [];
        document.querySelectorAll('section[id]').forEach(function(section) {
            arr.push({
                id: section.id,
                el: section,
                offset: section.offsetTop - 120
            });
        });
        return arr;
    }

    function updateActiveLink() {
        var navLinks = document.querySelectorAll('.dimsop-nav .nav-link');
        var scrollPos = window.pageYOffset || document.documentElement.scrollTop;
        var current = '';
        var path = window.location.pathname;
        var sections = getSections();

        sections.forEach(function(section) {
            if (scrollPos >= section.offset) {
                current = section.id;
            }
        });

        var firstSectionId = sections.length > 0 ? sections[0].id : '';
        var sectionToNav = {
            'banner': '/', 'iso': '/', 'nosotros': '/#nosotros',
            'metodologia': '/#unidades', 'unidades': '/#unidades',
            'cobertura': '/#unidades', 'aliados': '/#aliados',
            'contadores': '/#unidades', 'proyectos': '/#unidades',
            'blog': '/blog', 'contacto': '/#contacto'
        };
        var activeHref = sectionToNav[current] || '/';

        navLinks.forEach(function(link) {
            link.classList.remove('dimsop-nav-active');
            var href = link.getAttribute('href') || '';

            if (path === '/blog' && href === '/blog') {
                link.classList.add('dimsop-nav-active');
            } else if (path === '/' && href === activeHref) {
                link.classList.add('dimsop-nav-active');
            }
        });
    }

    window.addEventListener('scroll', updateActiveLink, { passive: true });
    updateActiveLink();

    var wrap = document.getElementById('dimsop-search-wrap');
    if (wrap) {
        wrap.addEventListener('click', function(e) {
            if (e.target.tagName === 'INPUT') return;
            wrap.classList.toggle('dimsop-search-open');
            var input = wrap.querySelector('input');
            if (wrap.classList.contains('dimsop-search-open') && input) {
                input.focus();
            }
        });
        document.addEventListener('click', function(e) {
            if (!wrap.contains(e.target)) {
                wrap.classList.remove('dimsop-search-open');
            }
        });
    }

    var burger = document.getElementById('dimsop-burger-toggle');
    var mobileNav = document.getElementById('dimsop-mobile-nav');
    if (burger && mobileNav) {
        function closeMobileMenu() {
            mobileNav.classList.remove('dimsop-mobile-open');
            burger.classList.remove('dimsop-burger-active');
            burger.setAttribute('aria-expanded', 'false');
            mobileNav.setAttribute('aria-hidden', 'true');
        }

        burger.addEventListener('click', function() {
            var isOpen = mobileNav.classList.contains('dimsop-mobile-open');
            if (isOpen) {
                closeMobileMenu();
            } else {
                mobileNav.classList.add('dimsop-mobile-open');
                burger.classList.add('dimsop-burger-active');
                burger.setAttribute('aria-expanded', 'true');
                mobileNav.setAttribute('aria-hidden', 'false');
            }
        });

        mobileNav.querySelectorAll('.nav-link').forEach(function(link) {
            link.addEventListener('click', function() {
                closeMobileMenu();
            });
        });

        document.addEventListener('click', function(e) {
            if (!burger.contains(e.target) && !mobileNav.contains(e.target)) {
                closeMobileMenu();
            }
        });
    }

    document.querySelectorAll('a[href^="/#"]').forEach(function(anchor) {
        anchor.addEventListener('click', function(e) {
            var hash = this.getAttribute('href');
            if (hash) {
                var target = document.querySelector(hash);
                if (target) {
                    e.preventDefault();
                    var headerHeight = header.offsetHeight || 70;
                    var targetPosition = target.getBoundingClientRect().top + window.pageYOffset - headerHeight;
                    window.scrollTo({ top: targetPosition, behavior: 'smooth' });
                }
            }
        });
    });
})();

(function() {
    var prefersReducedMotion = window.matchMedia &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) return;

    function loadGSAP(callback) {
        if (window.gsap && window.ScrollTrigger) { callback(); return; }
        var gsapScript = document.createElement('script');
        gsapScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js';
        gsapScript.onload = function () {
            var stScript = document.createElement('script');
            stScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js';
            stScript.onload = function () {
                gsap.registerPlugin(ScrollTrigger);
                callback();
            };
            document.head.appendChild(stScript);
        };
        document.head.appendChild(gsapScript);
    }

    function initAnimations() {
        gsap.config({ nullTargetWarn: false });

        gsap.from('#banner h1', { y: 40, opacity: 0, duration: 1, delay: 0.5, ease: 'power3.out' });
        gsap.from('#banner .dimsop-lead', { y: 30, opacity: 0, duration: 1, delay: 0.7, ease: 'power3.out' });

        var isMobile = window.innerWidth < 768;
        var nosotrosTl = gsap.timeline({
            scrollTrigger: { trigger: '#nosotros', start: 'top 75%', toggleActions: 'play none none reverse' }
        });
        nosotrosTl
            .from('#nosotros .dimsop-h2', { y: 40, opacity: 0, duration: 0.8, ease: 'power3.out' })
            .from('#nosotros .dimsop-lead', { y: 25, opacity: 0, duration: 0.7, ease: 'power3.out' }, '-=0.5');
        if (!isMobile) {
            nosotrosTl
                .from('#nosotros .col-lg-6:first-child .dimsop-card', { x: -60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.3')
                .from('#nosotros .col-lg-6:last-child .dimsop-card', { x: 60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.6');
        } else {
            nosotrosTl
                .from('#nosotros .col-lg-6:first-child .dimsop-card', { opacity: 0, duration: 0.6, ease: 'power3.out' }, '-=0.3')
                .from('#nosotros .col-lg-6:last-child .dimsop-card', { opacity: 0, duration: 0.6, ease: 'power3.out' }, '-=0.4');
        }
        nosotrosTl
            .from('#nosotros .dimsop-h3', { y: 30, opacity: 0, duration: 0.6, ease: 'power3.out' }, '-=0.3')
            .from('#nosotros .text-center.mb-4', { y: 20, opacity: 0, duration: 0.5, ease: 'power3.out' }, '-=0.4')
            .from('#nosotros .dimsop-value', { scale: 0.85, opacity: 0, duration: 0.5, stagger: 0.08, ease: 'back.out(1.4)' }, '-=0.3');

        gsap.from('#iso', {
            x: -60, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#iso', start: 'top 90%', toggleActions: 'play none none reverse' }
        });

        // Metodología: título + texto
        gsap.from('#metodologia .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#metodologia', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#metodologia .dimsop-metodologia-text', {
            y: 30, opacity: 0, duration: 0.6, ease: 'power2.out',
            scrollTrigger: { trigger: '#metodologia', start: 'top 75%', toggleActions: 'play none none reverse' }
        });

        // Metodología: imagen base
        var metBase = document.querySelector('#metodologia .dimsop-metodologia-base');
        if (metBase) {
            gsap.fromTo(metBase,
                { scale: 0.9, opacity: 0 },
                { scale: 1, opacity: 1, duration: 1, ease: 'power2.out', clearProps: 'all',
                  scrollTrigger: { trigger: '#metodologia .dimsop-metodologia-container', start: 'top 80%', toggleActions: 'play none none reverse' }
                }
            );
        }

        // Metodología: iconos con stagger (scale only, opacity controlled by CSS)
        var metIcons = document.querySelectorAll('#metodologia .dimsop-metodologia-icon');
        if (metIcons.length) {
            gsap.fromTo(metIcons,
                { scale: 0 },
                { scale: 1, duration: 0.5, stagger: 0.15, ease: 'back.out(1.7)', clearProps: 'transform',
                  scrollTrigger: { trigger: '#metodologia .dimsop-metodologia-container', start: 'top 70%', toggleActions: 'play none none reverse' }
                }
            );
        }

        // Metodología mobile: clip-path reveal
        var metMobile = document.querySelector('#metodologia .d-md-none img');
        if (metMobile) {
            gsap.fromTo(metMobile,
                { clipPath: 'inset(50% 50% 50% 50%)' },
                {
                    clipPath: 'inset(0% 0% 0% 0%)', duration: 1, ease: 'power3.out',
                    scrollTrigger: { trigger: '#metodologia', start: 'top 75%', toggleActions: 'play none none reverse' }
                }
            );
        }

        gsap.from('#unidades .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#unidades .dimsop-card', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.18, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades', start: 'top 80%', toggleActions: 'play none none none' }
        });

        gsap.from('#cobertura .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#cobertura', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        // Texto de sedes
        gsap.from('#cobertura .dimsop-cobertura-text > *', {
            opacity: 0, y: 20, duration: 0.5, stagger: 0.1, ease: 'power2.out',
            scrollTrigger: { trigger: '#cobertura .dimsop-cobertura-text', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        // Globe: clip-path reveal
        var coberturaGlobe = document.querySelector('#dimsop-globe-wrap');
        if (coberturaGlobe) {
            gsap.fromTo(coberturaGlobe,
                { clipPath: 'inset(10% 20% 10% 20%)', opacity: 0 },
                {
                    clipPath: 'inset(0% 0% 0% 0%)', opacity: 1, duration: 1.2, ease: 'power3.out',
                    scrollTrigger: { trigger: coberturaGlobe, start: 'top 80%', toggleActions: 'play none none reverse' }
                }
            );
        }

        gsap.from('#aliados .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#aliados', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        function resetContadores() {
            gsap.set('.dimsop-counter-box', { scale: 0.85, opacity: 0 });
            gsap.set('.dimsop-counter p', { y: 20, opacity: 0 });
            document.querySelectorAll('.dimsop-counter-num[data-target]').forEach(function(el) {
                var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
                el.textContent = prefix + '0';
            });
        }

        function animarContadores() {
            var tl = gsap.timeline();
            tl.to('.dimsop-counter-box', {
                scale: 1, opacity: 1, duration: 0.6,
                stagger: 0.2, ease: 'back.out(1.7)'
            });
            tl.to('.dimsop-counter p', {
                y: 0, opacity: 1, duration: 0.5,
                stagger: 0.2, ease: 'power2.out'
            }, '-=0.3');
            document.querySelectorAll('.dimsop-counter-num[data-target]').forEach(function(el) {
                var target = parseInt(el.getAttribute('data-target'), 10);
                var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
                var proxy = { val: 0 };
                tl.to(proxy, {
                    val: target,
                    duration: 1.8,
                    ease: 'power2.out',
                    onUpdate: function() {
                        el.textContent = prefix + Math.floor(proxy.val);
                    }
                }, 0);
            });
        }

        resetContadores();

        ScrollTrigger.create({
            trigger: '#contadores',
            start: 'top 80%',
            onEnter: function() { animarContadores(); },
            onEnterBack: function() { animarContadores(); },
            onLeave: function() {},
            onLeaveBack: function() { resetContadores(); }
        });

        gsap.from('#proyectos .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#proyectos', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#blog .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#blog .dimsop-blog-card', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#contacto .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#contacto .dimsop-form-card', {
            y: 30, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto .dimsop-form-card', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#dimsop_footer .col-lg-4', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#dimsop_footer', start: 'top 90%', toggleActions: 'play none none reverse' }
        });

        setTimeout(function() { ScrollTrigger.refresh(); }, 500);
    }

    loadGSAP(initAnimations);

    setTimeout(function() {
        if (!window.gsap) {
            document.querySelectorAll('.dimsop-counter-num[data-target]').forEach(function(el) {
                var target = el.getAttribute('data-target');
                var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
                el.textContent = prefix + target;
            });
            document.querySelectorAll('#banner h1, #banner .dimsop-lead, .dimsop-h2, .dimsop-lead, .dimsop-card, .dimsop-h3, .dimsop-value, .dimsop-step, .dimsop-counter-box, .dimsop-counter p, .dimsop-blog-card, .dimsop-form, #dimsop_footer .col-lg-4').forEach(function(el) {
                el.style.opacity = '1';
                el.style.transform = 'none';
            });
        }
    }, 3500);
})();

(function() {
    var form = document.querySelector('.dimsop-form');
    if (!form) return;

    var nombre = document.getElementById('dimsop-f-nombre');
    var correo = document.getElementById('dimsop-f-correo');
    var submitBtn = form.querySelector('.dimsop-btn-submit');

    function showError(input, errorId, msg) {
        var err = document.getElementById(errorId);
        input.classList.add('dimsop-is-invalid');
        input.classList.remove('dimsop-is-valid');
        input.setAttribute('aria-invalid', 'true');
        if (err) { err.textContent = msg; err.classList.add('is-visible'); }
    }

    function clearError(input, errorId) {
        var err = document.getElementById(errorId);
        input.classList.remove('dimsop-is-invalid');
        input.removeAttribute('aria-invalid');
        if (err) { err.textContent = ''; err.classList.remove('is-visible'); }
    }

    function markValid(input) {
        input.classList.remove('dimsop-is-invalid');
        input.classList.add('dimsop-is-valid');
        input.removeAttribute('aria-invalid');
    }

    function isValidEmail(v) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    }

    if (nombre) {
        nombre.addEventListener('blur', function() {
            var v = this.value.trim();
            if (v.length === 0) {
                showError(this, 'dimsop-e-nombre', 'El nombre es obligatorio.');
            } else if (v.length < 2) {
                showError(this, 'dimsop-e-nombre', 'El nombre debe tener al menos 2 caracteres.');
            } else {
                clearError(this, 'dimsop-e-nombre');
                markValid(this);
            }
        });
        nombre.addEventListener('input', function() {
            if (this.classList.contains('dimsop-is-invalid')) {
                var v = this.value.trim();
                if (v.length >= 2) { clearError(this, 'dimsop-e-nombre'); markValid(this); }
            }
        });
    }

    if (correo) {
        correo.addEventListener('blur', function() {
            var v = this.value.trim();
            if (v.length === 0) {
                showError(this, 'dimsop-e-correo', 'El correo electrónico es obligatorio.');
            } else if (!isValidEmail(v)) {
                showError(this, 'dimsop-e-correo', 'Ingresa un correo electrónico válido.');
            } else {
                clearError(this, 'dimsop-e-correo');
                markValid(this);
            }
        });
        correo.addEventListener('input', function() {
            if (this.classList.contains('dimsop-is-invalid')) {
                var v = this.value.trim();
                if (isValidEmail(v)) { clearError(this, 'dimsop-e-correo'); markValid(this); }
            }
        });
    }

    // Campo "Otro": show/hide segun seleccion
    var servicioSelect = document.getElementById('dimsop-f-servicio');
    var otroWrapper = document.getElementById('dimsop-otro-wrapper');
    if (servicioSelect && otroWrapper) {
        servicioSelect.addEventListener('change', function() {
            otroWrapper.style.display = this.value === 'other' ? 'block' : 'none';
        });
    }

    form.addEventListener('submit', function(e) {
        var valid = true;

        if (nombre) {
            var nv = nombre.value.trim();
            if (nv.length === 0) { showError(nombre, 'dimsop-e-nombre', 'El nombre es obligatorio.'); valid = false; }
            else if (nv.length < 2) { showError(nombre, 'dimsop-e-nombre', 'El nombre debe tener al menos 2 caracteres.'); valid = false; }
            else { clearError(nombre, 'dimsop-e-nombre'); markValid(nombre); }
        }

        if (correo) {
            var cv = correo.value.trim();
            if (cv.length === 0) { showError(correo, 'dimsop-e-correo', 'El correo electrónico es obligatorio.'); valid = false; }
            else if (!isValidEmail(cv)) { showError(correo, 'dimsop-e-correo', 'Ingresa un correo electrónico válido.'); valid = false; }
            else { clearError(correo, 'dimsop-e-correo'); markValid(correo); }
        }

        if (!valid) {
            e.preventDefault();
            var firstInvalid = form.querySelector('.dimsop-is-invalid');
            if (firstInvalid) firstInvalid.focus();
            return;
        }

        submitBtn.classList.add('dimsop-loading');
        submitBtn.disabled = true;
    });
})();

(function() {
    var urlParams = new URLSearchParams(window.location.search);
    var alertEl = null;
    if (urlParams.get('mensaje') === 'enviado') {
        alertEl = document.getElementById('dimsop-alert-success');
    } else if (urlParams.get('error') === 'datos_incompletos') {
        alertEl = document.getElementById('dimsop-alert-error');
    }
    if (alertEl) {
        alertEl.style.display = 'block';
        if (window.history && window.history.replaceState) {
            window.history.replaceState({}, '', window.location.pathname + '#contacto');
        }
        setTimeout(function() {
            alertEl.style.transition = 'opacity 0.4s ease';
            alertEl.style.opacity = '0';
            setTimeout(function() { alertEl.style.display = 'none'; }, 400);
        }, 5000);
    }
})();

(function() {
    var form = document.getElementById('dimsop-carreras-form');
    if (!form) return;

    var nombre = document.getElementById('carreras-nombre');
    var correo = document.getElementById('carreras-email');
    var cvInput = document.getElementById('carreras-cv');
    var cvLabel = document.getElementById('carreras-cv-label');
    var submitBtn = form.querySelector('.dimsop-btn-submit');

    function showError(input, msg) {
        input.classList.add('dimsop-is-invalid');
        input.classList.remove('dimsop-is-valid');
        input.setAttribute('aria-invalid', 'true');
        var err = input.parentNode.querySelector('.dimsop-field-error');
        if (err) { err.textContent = msg; err.classList.add('is-visible'); }
    }

    function clearError(input) {
        input.classList.remove('dimsop-is-invalid');
        input.removeAttribute('aria-invalid');
        var err = input.parentNode.querySelector('.dimsop-field-error');
        if (err) { err.textContent = ''; err.classList.remove('is-visible'); }
    }

    function markValid(input) {
        input.classList.remove('dimsop-is-invalid');
        input.classList.add('dimsop-is-valid');
        input.removeAttribute('aria-invalid');
    }

    function isValidEmail(v) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
    }

    if (nombre) {
        nombre.addEventListener('blur', function() {
            var v = this.value.trim();
            if (v.length === 0) { showError(this, 'El nombre es obligatorio.'); }
            else if (v.length < 2) { showError(this, 'El nombre debe tener al menos 2 caracteres.'); }
            else { clearError(this); markValid(this); }
        });
        nombre.addEventListener('input', function() {
            if (this.classList.contains('dimsop-is-invalid') && this.value.trim().length >= 2) { clearError(this); markValid(this); }
        });
    }

    if (correo) {
        correo.addEventListener('blur', function() {
            var v = this.value.trim();
            if (v.length === 0) { showError(this, 'El correo electrónico es obligatorio.'); }
            else if (!isValidEmail(v)) { showError(this, 'Ingresa un correo electrónico válido.'); }
            else { clearError(this); markValid(this); }
        });
        correo.addEventListener('input', function() {
            if (this.classList.contains('dimsop-is-invalid') && isValidEmail(this.value.trim())) { clearError(this); markValid(this); }
        });
    }

    if (cvInput && cvLabel) {
        cvInput.addEventListener('change', function() {
            var span = cvLabel.querySelector('span');
            if (this.files && this.files.length > 0) {
                if (span) span.textContent = this.files[0].name;
                cvLabel.classList.add('dimsop-file-selected');
            } else {
                if (span) span.textContent = 'Seleccionar archivo';
                cvLabel.classList.remove('dimsop-file-selected');
            }
        });
    }

    form.addEventListener('submit', function(e) {
        var valid = true;

        if (nombre) {
            var nv = nombre.value.trim();
            if (nv.length === 0) { showError(nombre, 'El nombre es obligatorio.'); valid = false; }
            else if (nv.length < 2) { showError(nombre, 'El nombre debe tener al menos 2 caracteres.'); valid = false; }
            else { clearError(nombre); markValid(nombre); }
        }

        if (correo) {
            var cv2 = correo.value.trim();
            if (cv2.length === 0) { showError(correo, 'El correo electrónico es obligatorio.'); valid = false; }
            else if (!isValidEmail(cv2)) { showError(correo, 'Ingresa un correo electrónico válido.'); valid = false; }
            else { clearError(correo); markValid(correo); }
        }

        if (!valid) {
            e.preventDefault();
            var firstInvalid = form.querySelector('.dimsop-is-invalid');
            if (firstInvalid) firstInvalid.focus();
            return;
        }

        submitBtn.classList.add('dimsop-loading');
        submitBtn.disabled = true;
    });
})();

(function() {
    function initCarrerasModal() {
        var triggers = document.querySelectorAll('[data-bs-target="#dimsop-carreras-modal"]');
        var modalEl = document.getElementById('dimsop-carreras-modal');
        if (!triggers.length || !modalEl) return;
        var backdrop = null;

        function openModal() {
            // Cerrar menú móvil si está abierto
            var mobileNav = document.getElementById('dimsop-mobile-nav');
            var burger = document.getElementById('dimsop-burger-toggle');
            if (mobileNav) mobileNav.classList.remove('dimsop-mobile-open');
            if (burger) {
                burger.classList.remove('dimsop-burger-active');
                burger.setAttribute('aria-expanded', 'false');
            }
            modalEl.classList.add('show');
            modalEl.style.display = 'block';
            document.body.classList.add('modal-open');
            backdrop = document.createElement('div');
            backdrop.className = 'modal-backdrop fade show';
            document.body.appendChild(backdrop);
            backdrop.addEventListener('click', closeModal);
        }

        function closeModal() {
            modalEl.classList.remove('show');
            modalEl.style.display = 'none';
            document.body.classList.remove('modal-open');
            if (backdrop) { backdrop.remove(); backdrop = null; }
        }

        triggers.forEach(function(trigger) {
            trigger.addEventListener('click', function(e) {
                e.preventDefault();
                openModal();
            });
        });

        var closeBtn = modalEl.querySelector('.btn-close');
        if (closeBtn) closeBtn.addEventListener('click', closeModal);

        modalEl.addEventListener('click', function(e) {
            if (e.target === modalEl) closeModal();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCarrerasModal);
    } else {
        initCarrerasModal();
    }
})();

(function() {
    try {
        var t = localStorage.getItem('dimsop-theme');
        document.documentElement.setAttribute('data-theme', t === 'light' ? 'light' : 'dark');
    } catch(e) {}
})();

(function() {
    var globeLoaded = false;
    var section = document.getElementById('cobertura');
    if (!section) return;

    var observer = new IntersectionObserver(function(entries) {
        if (entries[0].isIntersecting && !globeLoaded) {
            globeLoaded = true;
            observer.disconnect();
            window.process = window.process || { env: { NODE_ENV: 'production' } };
            var script = document.createElement('script');
            script.src = '//cdn.jsdelivr.net/npm/globe.gl';
            script.onload = function() {
                var fallback = document.getElementById('dimsop-globe-fallback');
                var container = document.getElementById('dimsop-globe');
                if (fallback) fallback.style.display = 'none';
                if (container) initGlobe(container);
            };
            document.head.appendChild(script);
        }
    }, { threshold: 0.15 });
    observer.observe(section);

    function initGlobe(container) {
        var redCountries = [
            { name: 'M\u00e9xico', code: 'Mexico' },
            { name: 'Costa Rica', code: 'Costa Rica' },
            { name: 'Colombia', code: 'Colombia' },
            { name: 'Per\u00fa', code: 'Peru' },
            { name: 'Chile', code: 'Chile' },
            { name: 'Argentina', code: 'Argentina' },
            { name: 'Espa\u00f1a', code: 'Spain' }
        ];
        var redCodes = redCountries.map(function(c) { return c.code; });
        var hqs = [
            { name: 'Miami', lat: 25.7617, lng: -80.1918 },
            { name: 'Caracas', lat: 10.4806, lng: -66.9036 }
        ];
        var markerSvg = '<svg viewBox="-4 0 36 36" width="16" height="16">'
            + '<path fill="#2ecc71" d="M14,0 C21.732,0 28,5.641 28,12.6 C28,23.963 14,36 14,36 C14,36 0,24.064 0,12.6 C0,5.641 6.268,0 14,0 Z"></path>'
            + '<circle fill="white" cx="14" cy="14" r="6"></circle></svg>';

        var world = new Globe(container)
            .backgroundColor('rgba(0,0,0,0)')
            .globeImageUrl('//cdn.jsdelivr.net/npm/three-globe/example/img/earth-dark.jpg')
            .polygonSideColor(function() { return 'rgba(0,0,0,0.5)'; })
            .polygonStrokeColor(function() { return '#222'; })
            .polygonCapColor(function(d) {
                return redCodes.indexOf(d.properties.ADMIN) !== -1
                    ? 'rgba(231,76,60,0.75)' : 'rgba(0,0,0,0)';
            })
            .polygonAltitude(function(d) {
                return redCodes.indexOf(d.properties.ADMIN) !== -1 ? 0.015 : 0;
            })
            .htmlElementsData([])
            .htmlElement(function(d) {
                var el = document.createElement('div');
                if (d.type === 'hq') {
                    el.className = 'headquarter-marker';
                    el.innerHTML = markerSvg + '<span class="headquarter-label">' + d.name + '</span>';
                } else {
                    el.className = 'country-label';
                    el.innerText = d.name;
                }
                return el;
            })
            .htmlElementVisibilityModifier(function(el, isVisible) {
                el.style.opacity = isVisible ? 1 : 0;
            });

        fetch('https://raw.githubusercontent.com/vasturiano/globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson')
            .then(function(res) { return res.json(); })
            .then(function(countries) {
                world.polygonsData(countries.features);
                var labels = countries.features
                    .filter(function(f) { return redCodes.indexOf(f.properties.ADMIN) !== -1; })
                    .map(function(f) {
                        var matched = redCountries.find(function(c) { return c.code === f.properties.ADMIN; });
                        var bbox = f.bbox;
                        return {
                            type: 'country',
                            name: matched ? matched.name : f.properties.ADMIN,
                            lat: bbox ? (bbox[1] + bbox[3]) / 2 : 0,
                            lng: bbox ? (bbox[0] + bbox[2]) / 2 : 0
                        };
                    });
                var allElements = hqs.map(function(hq) { return Object.assign({}, hq, { type: 'hq' }); }).concat(labels);
                world.htmlElementsData(allElements);
            });

        var ctrls = world.controls();
        ctrls.autoRotate = true;
        var rotSpeed = 1.5;
        ctrls.autoRotateSpeed = rotSpeed;
        world.width(container.clientWidth);
        world.height(container.clientHeight);
    }
})();

