    var p2 = document.createElement('link'); p2.rel='preconnect'; p2.href='https://fonts.gstatic.com'; p2.crossOrigin=''; h.appendChild(p2);
    var f = document.createElement('link'); f.rel='stylesheet'; f.href='https://fonts.googleapis.com/css2?family=Anton&family=Bebas+Neue&family=Arimo:wght@400;500;600;700&display=swap'; h.appendChild(f);
